"""Библиотека и личная история: дополнительные блоки существующего сайта."""

SOURCES = [
 ('croup', 'Круп у детей', 'Признаки, обращение за помощью и видео с объяснением врача.', 'NHS · английский', 'https://www.nhs.uk/conditions/croup/'),
 ('children', 'Первая помощь детям', 'Обучающие материалы для родителей: подготовиться до экстренной ситуации.', 'British Red Cross · английский', 'https://www.redcross.org.uk/first-aid/learn-first-aid-for-babies-and-children'),
 ('breathing', 'Без сознания, но дышит', 'Учебное видео по первой помощи взрослому человеку.', 'British Red Cross · английский', 'https://www.youtube.com/watch?v=5fK2oCiz8VU'),
 ('not-breathing', 'Без сознания и не дышит', 'Учебное видео по первой помощи взрослому человеку.', 'British Red Cross · английский', 'https://www.youtube.com/watch?v=gDmy0of0XAk'),
]

CHILD_STORY = '''<section class="section child-story" id="child-story"><div class="wrap"><div class="child-story-grid">
 <div class="story-night"><span class="eyebrow">Ещё одна история нашей семьи</span><span class="night-label">Ночью. Дома. Вдруг.</span><blockquote>«Папа,<br>я не могу<br><em>дышать».</em></blockquote><span>Слова сына, которые невозможно забыть.</span></div>
 <article class="story-copy"><span class="badge">Личный опыт основателя</span><h2>А если бы дома<br>ничего не было?</h2>
 <p>«Ночью сын вдруг начал резко кашлять — без остановки. Потом сказал: “Папа, я не могу дышать”. Кашель был такой сильный, что мне казалось: он сейчас лёгкие выплюнет.</p>
 <p>Хорошо, у нас дома были небулайзер и Пульмикорт, которые мы купили ещё три года назад по совету врача. А если бы их не было?»</p>
 <p>Так основатель вспоминает эпизод, который он описывает как приступ ложного крупа. Эта история — ещё одна причина появления SAFEBOX: заранее обсудить с врачом нужные средства, знать, где они лежат, и держать назначения под рукой.</p>
 <aside class="notice small">Это личный рассказ, а не подтверждение диагноза или рекомендация применять препарат. Давняя покупка не означает, что лекарство ещё пригодно: проверяйте срок годности и условия хранения. Применение — по актуальному назначению врача. При выраженном затруднении дыхания нужна экстренная помощь: <a href="tel:112">112</a> / <a href="tel:103">103</a>. <a href="https://www.nhs.uk/conditions/croup/" target="_blank" rel="noopener noreferrer">Признаки опасности: NHS ↗</a></aside>
 </article></div></div></section>'''

def extend(content, section, heading, intro, button):
 resources = section(heading('Знания рядом с аптечкой', 'Не только хранить.<br>Понимать, где найти ответ.', 'Материалы для подготовки, разговор с врачом и бумажная опора — в одном месте.') + '''<div class="resource-grid">
 <a class="resource-card" href="qr-library.html"><span class="resource-symbol">▦</span><span class="num">01 / QR-библиотека</span><h3>Отсканировать.<br>Открыть. Изучить.</h3><p>QR-коды на проверенные образовательные источники. Открывайте с телефона или сохраняйте для печати.</p><b>Открыть библиотеку ↗</b></a>
 <a class="resource-card" href="video-library.html"><span class="resource-symbol">▷</span><span class="num">02 / Видеобиблиотека</span><h3>Увидеть,<br>чтобы разобраться.</h3><p>Видеоуроки по первой помощи и объяснения специалистов. Учиться лучше заранее.</p><b>Смотреть материалы ↗</b></a>
 <a class="resource-card" href="printed-guide.html"><span class="resource-symbol">▤</span><span class="num">03 / Печатная методичка</span><h3>Важное —<br>на бумаге.</h3><p>Раздел о будущем печатном издании и бесплатный лист подготовки аптечки уже сейчас.</p><b>О методичке и покупке ↗</b></a>
 <a class="resource-card resource-ai" href="assistant.html"><span class="resource-symbol">✳</span><span class="num">04 / ИИ-помощник</span><h3>Что нужно дома.<br>И почему.</h3><p>Идея ИИ-модуля: объяснять предложения для обсуждения с врачом. Сейчас работает конструктор вопросов.</p><b>Подготовить список вопросов ↗</b></a>
 </div>''', 'resources-section')
 # История следует за существующим рассказом основателя, остальные секции сохраняются.
 marker = '<section class="section care-section'
 content['index'] = content['index'].replace(marker, CHILD_STORY + marker, 1)
 content['index'] = content['index'].replace('<section class="section ">', resources + '<section class="section ">', 1)
 content['about'] += CHILD_STORY
 content['stories'] += CHILD_STORY
 nav = '<div class="resource-tabs"><a href="qr-library.html">QR-библиотека</a><a href="video-library.html">Видеобиблиотека</a><a href="printed-guide.html">Печатная методичка</a><a href="assistant.html">ИИ-помощник</a></div>'
 qr_cards = ''.join(f'''<article class="card qr-card"><img src="assets/qr/{key}.svg" width="168" height="168" alt="QR-код: {title}" loading="lazy"><div><span class="eyebrow">{publisher}</span><h2>{title}</h2><p>{desc}</p><a class="btn" href="{url}" target="_blank" rel="noopener noreferrer">Открыть источник ↗</a><a class="qr-download" href="assets/qr/{key}.svg" download>Скачать QR для печати ↓</a></div></article>''' for key,title,desc,publisher,url in SOURCES)
 content['qr-library'] = intro('Библиотека SAFEBOX', 'Нужный материал.<br>Одно сканирование.', 'Открывайте образовательные материалы с телефона по QR-коду или переходите по ссылке на этом устройстве.') + section(nav + '<p class="notice">Коды ведут на внешние ресурсы NHS и British Red Cross на английском языке, а не на персональные назначения. Нужен интернет. Материалы предназначены для заблаговременного обучения.</p><div class="grid two">' + qr_cards + '</div>')
 video_cards = ''.join(f'''<article class="card video-card"><a class="video-cover" href="{url}" target="_blank" rel="noopener noreferrer" aria-label="Смотреть: {title}"><span aria-hidden="true">▷</span><strong>{title}</strong></a><span class="eyebrow">{publisher}</span><h2>{title}</h2><p>{desc}</p>{button('Смотреть на сайте источника',url)}</article>''' for key,title,desc,publisher,url in [SOURCES[0], SOURCES[2], SOURCES[3]])
 content['video-library'] = intro('Видеобиблиотека', 'Посмотреть заранее.<br>Запомнить главное.', 'Подборка открытых обучающих видео. У каждого материала указан автор; просмотр открывается на внешнем сайте.') + section(nav + '<div class="notice">Видео на английском языке. Номера экстренных служб в зарубежных материалах отличаются: в России — 112 и 103. В экстренной ситуации обращайтесь за помощью, не тратьте время на поиск видео.</div><div class="grid">' + video_cards + '</div>') + section(heading('Собственные материалы SAFEBOX', 'Следующие видео — о вашей системе.') + '<div class="grid"><article class="card"><span class="badge">Планируется</span><h3>Как разложить аптечку</h3><p>От назначения врача до понятной маркировки разделов.</p></article><article class="card"><span class="badge">Планируется</span><h3>Как проверять содержимое</h3><p>Учёт сроков, целостности упаковок и условий хранения.</p></article><article class="card"><span class="badge">Планируется</span><h3>Как познакомить семью с SAFEBOX</h3><p>Где найти инструкции и как пользоваться библиотекой.</p></article></div>')
 content['printed-guide'] = intro('Печатная методичка', 'Когда важное<br>лежит под рукой.', 'Бумажная опора рядом с аптечкой: структура хранения, индивидуальные назначения и контакты, которые легко найти.') + section(nav + '''<div class="split"><div class="guide-cover"><span>SAFE<span>BOX</span></span><h2>Домашняя<br>аптечка.<br>Порядок<br>и подготовка.</h2><p>Концепция печатной методички</p><b>01 — Хранение<br>02 — Список семьи<br>03 — Проверка</b></div><div><span class="badge">Печатное издание готовится</span><h2>Купить печатную методичку</h2><p>Планируем отдельное издание для тех, кому удобнее бумага. Цена, объём, доставка и дата начала продаж пока не утверждены.</p><button class="btn primary" disabled>Продажи ещё не открыты</button><p class="small muted">Оплата и оформление заказа пока недоступны.</p><h3>Что планируется внутри</h3><ul class="points"><li>Карта размещения средств в SAFEBOX</li><li>Листы для назначений врача и индивидуальных ограничений</li><li>Журнал проверки сроков и пополнения</li><li>Контакты семьи и QR-ссылки на обучающие материалы</li></ul></div></div>''') + section('''<div class="card printable-sheet" id="guide-sample"><span class="eyebrow">Бесплатный лист подготовки · образец, не методичка</span><h2>Начните с порядка уже сейчас.</h2><p>Распечатайте лист и заполните его вместе с близкими. Названия и схемы применения лекарств вносите по назначениям врача.</p><div class="grid two"><div><h3>Где находится аптечка?</h3><p>________________________________</p><h3>Где хранятся назначения?</h3><p>________________________________</p></div><div><h3>Дата проверки / следующая проверка</h3><p>________________________________</p><h3>Что нужно уточнить у врача?</h3><p>________________________________</p></div></div><ul class="points"><li>Проверены сроки годности и условия хранения</li><li>Средства остаются в подписанной оригинальной упаковке</li><li>Взрослые знают расположение; дети не имеют свободного доступа</li><li>Записаны контакты близких и экстренных служб</li></ul><button class="btn" type="button" id="print-guide">Распечатать лист ↓</button></div>''')
 content['assistant'] = content['assistant'].replace('Подготовьтесь<br>к разговору с врачом.', 'Какие лекарства нужны дома.<br>И почему именно они.').replace('Будущий ИИ-модуль задуман для подготовки рекомендаций к согласованию со специалистом. Сейчас доступен конструктор вопросов без автоматического подбора лекарств.', 'ИИ-помощник задуман для объяснимого подбора домашней аптечки: что обсудить с врачом, для чего это может понадобиться и какие ограничения учесть. Сейчас работает конструктор вопросов и целей подготовки; подключение ИИ — следующий этап.')
 content['assistant'] += section(heading('От списка — к пониманию', 'У каждого предложения<br>должно быть объяснение.') + '<div class="grid"><article class="card"><h3>Для чего?</h3><p>Какую задачу решает средство и нужно ли оно вашей семье — вопрос для согласования с врачом.</p></article><article class="card"><h3>Какие ограничения?</h3><p>Возраст, противопоказания и совместимость с уже назначенными препаратами должны быть проверены специалистом.</p></article><article class="card"><h3>Как хранить?</h3><p>Условия по инструкции, срок после вскрытия и понятное место в аптечке.</p></article></div>')
